div.script:
function previewImage(input) {
    if (input.files && input.files[0]) {
        var file = input.files[0];
        var hint = document.getElementById('file_hint');

        if (file.size > 5 * 1024 * 1024) {
            input.value = '';
            showPopup('warning', 'File Terlalu Besar', 'Ukuran file maksimal 5MB.');
            return;
        }

        if (!['image/jpeg', 'image/png'].includes(file.type)) {
            input.value = '';
            showPopup('warning', 'Format Tidak Didukung', 'Gunakan file JPG atau PNG.');
            return;
        }

        var reader = new FileReader();

        document.getElementById('upload_prompt').classList.add('tw-hidden');
        document.getElementById('image_preview_container').classList.add('tw-hidden');
        document.getElementById('loading_state').classList.remove('tw-hidden');

        reader.onload = function(e) {
            var img = new Image();
            img.onload = function() {
                if (img.width < 600 || img.height < 350) {
                    input.value = '';
                    document.getElementById('loading_state').classList.add('tw-hidden');
                    document.getElementById('upload_prompt').classList.remove('tw-hidden');
                    showPopup('warning', 'Resolusi Terlalu Kecil', 'Upload foto KTM minimal 600x350 px agar NIM dan nama terbaca.');
                    return;
                }

                document.getElementById('loading_state').classList.add('tw-hidden');
                document.getElementById('image_preview_container').classList.remove('tw-hidden');
                document.getElementById('image_preview').src = e.target.result;
                if (hint) {
                    hint.textContent = 'Preview siap. Pastikan NIM dan nama terlihat jelas sebelum submit.';
                    hint.className = 'tw-font-normal tw-text-[11px] md:tw-text-[12px] tw-text-green-600 tw-mt-2 tw-mb-0 tw-text-left';
                }
            };
            img.src = e.target.result;
        };

        reader.readAsDataURL(file);
    }
}

/* ===== AJAX Form Submit ===== */
document.addEventListener('DOMContentLoaded', function() {
    var form = document.getElementById('ktm_form');
    if (!form) return;
    initUniversitySelect();

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        var universityInput = document.getElementById('university_id');
        var universityOtherInput = document.getElementById('university_other');
        var hasUniversity = universityInput && universityInput.value;
        var hasOtherUniversity = universityOtherInput && universityOtherInput.value.trim();
        if (!hasUniversity && !hasOtherUniversity) {
            showPopup('warning', 'Pilih Universitas', 'Pilih universitas dari daftar atau isi universitas lainnya terlebih dahulu.');
            return;
        }

        var fileInput = document.getElementById('ktm_file');
        if (!fileInput.files || !fileInput.files[0]) {
            showPopup('error', 'Oops!', 'Pilih file KTM terlebih dahulu.');
            return;
        }

        // Show loading state on button
        var btnText = document.getElementById('btn_text');
        var btnSpinner = document.getElementById('btn_spinner');
        var btnSubmit = document.getElementById('btn_submit');
        btnText.textContent = 'MEMPROSES...';
        btnSpinner.classList.remove('tw-hidden');
        btnSubmit.disabled = true;
        btnSubmit.classList.add('tw-opacity-70');

        var formData = new FormData(form);

        fetch('/seller-verification/submit', {
            method: 'POST',
            body: formData,
        })
        .then(function(response) { return response.json(); })
        .then(function(data) {
            // Reset button
            btnText.textContent = 'UPLOAD KTM';
            btnSpinner.classList.add('tw-hidden');
            btnSubmit.disabled = false;
            btnSubmit.classList.remove('tw-opacity-70');

            if (data.status === 'approved') {
                showPopup('success', 'Verifikasi Berhasil ✅', data.message || 'Pengajuan verifikasi berhasil.');
            } else if (data.status === 'manual_review') {
                showPopup('manual_review', 'Masuk Review Manual', data.message || 'Pengajuan Anda sedang direview admin.');
            } else if (data.status === 'otp_required') {
                window.location.href = data.redirect_url || '/seller-onboarding';
            } else if (data.status === 'rate_limited') {
                showPopup('warning', 'Terlalu Banyak Percobaan', data.message || 'Coba lagi beberapa menit lagi.');
            } else if (data.status === 'rejected') {
                showPopup('rejected', 'Pengajuan Ditolak ❌', data.message || 'Pastikan Anda mahasiswa UNISA.');
            } else if (data.status === 'invalid_image') {
                showPopup('warning', 'Gambar Tidak Sesuai', data.message || 'Coba lagi dengan foto KTM yang benar.');
            } else if (data.status === 'no_name') {
                showPopup('warning', 'Foto Tidak Valid', data.message || 'Pastikan upload foto KTM');
            } else {
                showPopup('error', 'Terjadi Kesalahan', data.message || 'Silakan coba lagi.');
            }
        })
        .catch(function(err) {
            btnText.textContent = 'UPLOAD KTM';
            btnSpinner.classList.add('tw-hidden');
            btnSubmit.disabled = false;
            btnSubmit.classList.remove('tw-opacity-70');
            showPopup('error', 'Koneksi Gagal', 'Tidak dapat menghubungi server. Periksa koneksi Anda.');
        });
    });
});

function initUniversitySelect() {
    var searchInput = document.getElementById('university_search');
    var hiddenInput = document.getElementById('university_id');
    var dropdown = document.getElementById('university_dropdown');
    var toggle = document.getElementById('university_toggle');
    var empty = document.getElementById('university_empty');
    var otherButton = document.getElementById('university_other_button');
    var otherWrap = document.getElementById('university_other_wrap');
    var otherInput = document.getElementById('university_other');
    var options = Array.prototype.slice.call(document.querySelectorAll('[data-university-option="1"]'));
    if (!searchInput || !hiddenInput || !dropdown) return;

    function openDropdown() {
        dropdown.classList.remove('tw-hidden');
        filterOptions(searchInput.value);
    }

    function closeDropdown() {
        dropdown.classList.add('tw-hidden');
    }

    function normalize(text) {
        return (text || '').toLowerCase().trim();
    }

    function filterOptions(query) {
        var needle = normalize(query);
        var visibleCount = 0;
        options.forEach(function(option) {
            var name = normalize(option.getAttribute('data-university-name'));
            var isVisible = !needle || name.indexOf(needle) !== -1;
            option.classList.toggle('tw-hidden', !isVisible);
            if (isVisible) visibleCount += 1;
        });
        if (empty) {
            empty.classList.toggle('tw-hidden', visibleCount !== 0);
        }
    }

    function showOtherField(initialValue) {
        hiddenInput.value = '';
        searchInput.value = initialValue || 'Universitas lainnya';
        if (otherWrap) {
            otherWrap.classList.remove('tw-hidden');
        }
        if (otherInput && initialValue && initialValue !== 'Universitas lainnya') {
            otherInput.value = initialValue;
        }
        closeDropdown();
        if (otherInput) {
            otherInput.focus();
        }
    }

    function hideOtherField() {
        if (otherWrap) {
            otherWrap.classList.add('tw-hidden');
        }
        if (otherInput) {
            otherInput.value = '';
        }
    }

    searchInput.addEventListener('focus', openDropdown);
    searchInput.addEventListener('input', function() {
        hiddenInput.value = '';
        hideOtherField();
        openDropdown();
    });
    if (toggle) {
        toggle.addEventListener('click', function() {
            if (dropdown.classList.contains('tw-hidden')) {
                searchInput.focus();
                openDropdown();
            } else {
                closeDropdown();
            }
        });
    }
    options.forEach(function(option) {
        option.addEventListener('click', function() {
            hiddenInput.value = option.getAttribute('data-university-id') || '';
            searchInput.value = option.getAttribute('data-university-name') || '';
            hideOtherField();
            closeDropdown();
        });
    });
    if (otherButton) {
        otherButton.addEventListener('click', function() {
            var typedValue = searchInput.value.trim();
            showOtherField(typedValue || 'Universitas lainnya');
        });
    }
    document.addEventListener('click', function(event) {
        if (!dropdown.contains(event.target) && event.target !== searchInput && event.target !== toggle && !(toggle && toggle.contains(event.target)) && !(otherWrap && otherWrap.contains(event.target))) {
            closeDropdown();
        }
    });
}

/* ===== Popup Functions ===== */
function showPopup(type, title, message) {
    var popup = document.getElementById('result_popup');
    var iconEl = document.getElementById('popup_icon');
    var titleEl = document.getElementById('popup_title');
    var msgEl = document.getElementById('popup_message');
    var popupType = type || 'error';
    var popupConfig = {
        success: {
            title: 'Pengajuan Diterima',
            message: 'Selamat pengajuan anda diterima',
            icon: ''
        },
        warning: {
            title: 'Gambar tidak sesuai',
            message: 'Gambar tidak sesuai, silahkan coba lagi',
            icon: ''
        },
        manual_review: {
            title: 'Masuk Review Manual',
            message: 'Pengajuan Anda sedang direview admin',
            icon: ''
        },
        rejected: {
            title: 'Pengajuan Ditolak',
            message: 'Pengajuan anda ditolak pastikan mahasiswa anda mahasiswa UNISA',
            icon: ''
        },
        error: {
            title: title || 'Terjadi Kesalahan',
            message: message || 'Silakan coba lagi.',
            icon: ''
        }
    }[popupType] || {};

    popup.classList.remove('ut-verification-result-success', 'ut-verification-result-warning', 'ut-verification-result-manual_review', 'ut-verification-result-rejected', 'ut-verification-result-error');
    popup.classList.add('ut-verification-result-' + popupType);
    titleEl.textContent = popupConfig.title || title || 'Terjadi Kesalahan';
    msgEl.textContent = popupConfig.message || message || 'Silakan coba lagi.';
    iconEl.className = 'ut-verification-result-icon';
    iconEl.innerHTML = popupConfig.icon || '';
    popup.setAttribute('aria-hidden', 'false');
    popup.classList.remove('tw-hidden');
    return;

    titleEl.textContent = title;
    msgEl.textContent = message;

    // Set icon + color based on type
    if (type === 'success') {
        iconEl.className = 'tw-w-[72px] tw-h-[72px] tw-rounded-full tw-flex tw-items-center tw-justify-center tw-mb-5 tw-bg-green-100';
        iconEl.innerHTML = '';
    } else if (type === 'rejected') {
        iconEl.className = 'tw-w-[72px] tw-h-[72px] tw-rounded-full tw-flex tw-items-center tw-justify-center tw-mb-5 tw-bg-red-100';
        iconEl.innerHTML = '';
    } else if (type === 'warning') {
        iconEl.className = 'tw-w-[72px] tw-h-[72px] tw-rounded-full tw-flex tw-items-center tw-justify-center tw-mb-5 tw-bg-yellow-100';
        iconEl.innerHTML = '';
    } else {
        iconEl.className = 'tw-w-[72px] tw-h-[72px] tw-rounded-full tw-flex tw-items-center tw-justify-center tw-mb-5 tw-bg-gray-100';
        iconEl.innerHTML = '';
    }

    popup.classList.remove('tw-hidden');
}

function closePopup() {
    var popup = document.getElementById('result_popup');
    popup.classList.add('tw-hidden');
    popup.setAttribute('aria-hidden', 'true');
    // Reload page to refresh status banner
    window.location.reload();
}
